    cwd: scratch.cwd,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
    maxBuffer: 8 * 1024 * 1024,
  });
  if (dirty.trim().length > 0) {
    throw new Error('managed host run: managed-review scratch contains provider-created or modified material');
  }
}

