    promptDigest: draft.promptDigest,
    ...(draft.receiptId ? { receiptId: draft.receiptId } : {}),
    issuedAt,
    note: draft.note,
  };
  return {
    ...base,
    verdictId: `verdict-${canonicalDigest(base).slice(0, 16)}`,
